-- Run this one incremental file for the resume review improvements.
-- Scoring status uses existing category JSON. The two generated tokens protect content and job-ad saves.
-- A compact compare-and-swap token for review edits. Generated by Postgres so all
-- editor/review writes update it automatically, without sending resume JSON in URL filters.
-- Existing RLS and column update grants remain unchanged.
alter table public.resumes
  add column if not exists review_edit_token text
  generated always as (
    md5(coalesce(resume_content::text, 'null') || ':' || coalesce(review_findings::text, 'null'))
  ) stored;

-- Compact job-ad comparison keeps long advertisements out of request URLs.
alter table public.resumes
  add column if not exists review_job_ad_token text
  generated always as (md5(coalesce(job_description, ''))) stored;

-- Verify both generated tokens after applying this one file.
select column_name, data_type, is_generated
from information_schema.columns
where table_schema = 'public'
  and table_name = 'resumes'
  and column_name in ('review_edit_token', 'review_job_ad_token');

-- Job identity independent of the profile/upload cache key used by Skill Gap.
alter table public.skills_bridges
  add column if not exists job_ad_hash text;

select column_name, data_type from information_schema.columns
where table_schema = 'public' and table_name = 'skills_bridges' and column_name = 'job_ad_hash';
